import { test, expect } from '@playwright/test';

test.describe('Modal Dialog Animation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/modal-dialog');
  });

  test('should open modal with animation when button is clicked', async ({ page }) => {
    // Verify modal is not visible initially
    const modal = page.getByRole('dialog');
    await expect(modal).not.toBeVisible();

    // Get modal button by role
    const openButton = page.getByRole('button', { name: /open modal/i });
    await expect(openButton).toBeVisible();

    // Click open button to trigger modal
    await openButton.click();

    // Verify modal is now visible
    await expect(modal).toBeVisible();

    // Verify modal has animation class
    const animationClass = page.getByTestId('modal-animation');
    await expect(animationClass).toBeVisible();

    // Verify modal content is displayed
    const modalContent = page.getByRole('region', { name: /modal content/i });
    await expect(modalContent).toBeVisible();

    // Verify close button is present
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify modal is centered
    const modalCenter = page.getByTestId('modal-center');
    await expect(modalCenter).toBeVisible();
  });

  test('should close modal with animation when close button is clicked', async ({ page }) => {
    // Open modal
    const openButton = page.getByRole('button', { name: /open modal/i });
    await openButton.click();

    // Verify modal is visible
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    // Get close button by role
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Click close button to trigger modal closure
    await closeButton.click();

    // Verify modal is no longer visible
    await expect(modal).not.toBeVisible();

    // Verify modal animation class is removed
    const animationClass = page.getByTestId('modal-animation');
    await expect(animationClass).not.toBeVisible();

    // Verify modal content is no longer displayed
    const modalContent = page.getByRole('region', { name: /modal content/i });
    await expect(modalContent).not.toBeVisible();

    // Verify modal is centered
    const modalCenter = page.getByTestId('modal-center');
    await expect(modalCenter).not.toBeVisible();
  });
});
